import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { dirname, join, relative, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const xsdRoot = join(root, "regulatory", "official", "dgfip", "v3.2", "xsd", "2 - E-invoicing");
const target = join(root, "src", "generated", "xsd-bundle.ts");
const externalRoots = [
  ["annuaire", join(root, "regulatory", "official", "dgfip", "v3.2", "xsd", "0 - Annuaire")],
  ["e-reporting", join(root, "regulatory", "official", "dgfip", "v3.2", "xsd", "1 - E-reporting")],
];
const externalTarget = join(root, "src", "generated", "external-xsd-bundle.ts");
const oasisUblRoot = join(root, "regulatory", "official", "oasis", "ubl-2.1", "xsdrt");
const oasisUblTarget = join(root, "src", "generated", "oasis-ubl-xsd-bundle.ts");

function files(directory) {
  return readdirSync(directory, { withFileTypes: true })
    .flatMap((entry) => entry.isDirectory() ? files(join(directory, entry.name)) : [join(directory, entry.name)])
    .filter((path) => path.endsWith(".xsd") && !path.split(sep).some((part) => part.startsWith("._")))
    .sort();
}

const schemas = files(xsdRoot);
const entries = schemas.map((path) => {
  const key = relative(xsdRoot, path).split(sep).join("/");
  return `  ${JSON.stringify(key)}: ${JSON.stringify(readFileSync(path, "utf8"))},`;
});

writeFileSync(target, [
  "// Generated by scripts/generate-xsd-bundle.mjs. Do not edit manually.",
  "export const XSD_TEXT_BY_PATH: Readonly<Record<string, string>> = {",
  ...entries,
  "};",
  "",
].join("\n"));

console.log(`Wrote ${target} with ${schemas.length} official DGFiP schemas.`);

const externalEntries = externalRoots.flatMap(([prefix, directory]) => files(directory).map((path) => {
  const key = [prefix, relative(directory, path).split(sep).join("/")].join("/");
  return `  ${JSON.stringify(key)}: ${JSON.stringify(readFileSync(path, "utf8"))},`;
}));

writeFileSync(externalTarget, [
  "// Generated by scripts/generate-xsd-bundle.mjs. Do not edit manually.",
  "export const EXTERNAL_XSD_TEXT_BY_PATH: Readonly<Record<string, string>> = {",
  ...externalEntries,
  "};",
  "",
].join("\n"));

console.log(`Wrote ${externalTarget} with ${externalEntries.length} official DGFiP schemas.`);

const oasisUblEntries = files(oasisUblRoot).map((path) => {
  const key = ["oasis-ubl-2.1", relative(oasisUblRoot, path).split(sep).join("/")].join("/");
  return `  ${JSON.stringify(key)}: ${JSON.stringify(readFileSync(path, "utf8"))},`;
});

writeFileSync(oasisUblTarget, [
  "// Generated by scripts/generate-xsd-bundle.mjs. Do not edit manually.",
  "export const OASIS_UBL_XSD_TEXT_BY_PATH: Readonly<Record<string, string>> = {",
  ...oasisUblEntries,
  "};",
  "",
].join("\n"));

console.log(`Wrote ${oasisUblTarget} with ${oasisUblEntries.length} official OASIS UBL 2.1 schemas.`);
